[InitializeOnLoad]public static class FinalSignExpansionAudit{static FinalSignExpansionAudit(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalSignExpansionAudit.request")||EditorApplication.isCompiling)return;File.Delete("FinalSignExpansionAudit.request");var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).ToArray();var log=new StringBuilder();foreach(var r in all.Where(r=>r.name.ToLower().Contains("bridge")||r.name.Contains("Concrete walls")||r.transform.parent&&r.transform.parent.name.Contains("Bridge")) )log.AppendLine("BRIDGE "+r.name+" bounds="+r.bounds+" path="+AnimationUtility.CalculateTransformPath(r.transform,null));foreach(string name in new[]{"building551","building541","building531","building52","Building","building 1","defaultMaterial","Hyp"}){var r=all.FirstOrDefault(r=>r.name==name);if(!r)continue;var p=r.bounds.center;typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{s,p+new Vector3(r.bounds.size.x*.9f,r.bounds.size.y*.3f,-r.bounds.size.z*1.5f),p,"Sign-Audit-"+name.Replace(" ","_")});log.AppendLine("MODEL "+name+" "+r.bounds);}File.WriteAllText("FinalEnvironmentRoadReview/SignExpansionAudit.txt",log.ToString());}}
